import { describe, expect, it } from "vitest";
import { validateTraceArchive } from "@/lib/trace-archive";

// Playwright 1.62 trace generated by context.tracing for a page create/setContent/click flow.
const PLAYWRIGHT_TRACE_BASE64 =
  "";

function little16(value: number): number[] {
  return [value & 0xff, (value >>> 8) & 0xff];
}

function little32(value: number): number[] {
  return [value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff];
}

function zip(entryNames: string[], encrypted = false): Uint8Array {
  const encoder = new TextEncoder();
  const localParts: number[][] = [];
  const centralParts: number[][] = [];
  let localOffset = 0;
  const flags = encrypted ? 1 : 0;

  for (const entryName of entryNames) {
    const name = [...encoder.encode(entryName)];
    const local = [
      ...little32(0x04034b50),
      ...little16(20),
      ...little16(flags),
      ...little16(0),
      ...little16(0),
      ...little16(0),
      ...little32(0),
      ...little32(0),
      ...little32(0),
      ...little16(name.length),
      ...little16(0),
      ...name,
    ];
    localParts.push(local);
    centralParts.push([
      ...little32(0x02014b50),
      ...little16(20),
      ...little16(20),
      ...little16(flags),
      ...little16(0),
      ...little16(0),
      ...little16(0),
      ...little32(0),
      ...little32(0),
      ...little32(0),
      ...little16(name.length),
      ...little16(0),
      ...little16(0),
      ...little16(0),
      ...little16(0),
      ...little32(0),
      ...little32(localOffset),
      ...name,
    ]);
    localOffset += local.length;
  }

  const central = centralParts.flat();
  const eocd = [
    ...little32(0x06054b50),
    ...little16(0),
    ...little16(0),
    ...little16(entryNames.length),
    ...little16(entryNames.length),
    ...little32(central.length),
    ...little32(localOffset),
    ...little16(0),
  ];
  return Uint8Array.from([...localParts.flat(), ...central, ...eocd]);
}

describe("validateTraceArchive", () => {
  it("accepts a real Playwright trace ZIP", () => {
    const archive = new Uint8Array(Buffer.from(PLAYWRIGHT_TRACE_BASE64, "base64"));
    expect(validateTraceArchive(archive, archive.length)).toBeNull();
  });

  it("accepts multi-context trace entry names", () => {
    const archive = zip(["0-trace.trace", "0-trace.network"]);
    expect(validateTraceArchive(archive, archive.length)).toBeNull();
  });

  it("rejects an arbitrary ZIP", () => {
    const archive = zip(["notes.txt"]);
    expect(validateTraceArchive(archive, archive.length)).toMatch(/not a recognized/);
  });

  it("rejects empty and garbage buffers", () => {
    expect(validateTraceArchive(new Uint8Array(), 0)).toMatch(/not a recognized/);
    expect(validateTraceArchive(Uint8Array.from([1, 2, 3]), 3)).toMatch(/not a recognized/);
  });

  it("rejects encrypted entries", () => {
    const archive = zip(["trace.trace", "trace.network"], true);
    expect(validateTraceArchive(archive, archive.length)).toMatch(/not a recognized/);
  });

  it.each([
    ["entry counts", (data: DataView, eocd: number) => {
      data.setUint16(eocd + 8, 0xffff, true);
      data.setUint16(eocd + 10, 0xffff, true);
    }],
    ["directory size", (data: DataView, eocd: number) => {
      data.setUint32(eocd + 12, 0xffffffff, true);
    }],
    ["directory offset", (data: DataView, eocd: number) => {
      data.setUint32(eocd + 16, 0xffffffff, true);
    }],
  ])("rejects Zip64 %s sentinels", (_label, mutate) => {
    const archive = zip(["trace.trace", "trace.network"]);
    mutate(new DataView(archive.buffer), archive.length - 22);
    expect(validateTraceArchive(archive, archive.length)).toMatch(/not a recognized/);
  });

  it("rejects when the fetched tail does not contain the EOCD", () => {
    const archive = zip(["trace.trace", "trace.network"]);
    const incompleteTail = archive.subarray(0, archive.length - 22);
    expect(validateTraceArchive(incompleteTail, archive.length)).toMatch(/not a recognized/);
  });

  it("rejects when the central directory is outside the fetched tail", () => {
    const archive = zip(["trace.trace", "trace.network"]);
    const eocdOnly = archive.subarray(archive.length - 22);
    expect(validateTraceArchive(eocdOnly, archive.length)).toMatch(/not a recognized/);
  });
});
